"""Render evidence-led release readiness workspaces to HTML, SVG, JSON and CSV."""
import argparse,base64,csv,html,io,json,sys,textwrap
from datetime import date
from pathlib import Path

CLASSIFICATIONS=('mandatory','exceptionable','follow_up')
STATUSES=('passed','failed','not_run','unknown','accepted_exception')
ACCEPTANCE=('accepted','rejected','pending','not_required')
DECISIONS=('pending','go','conditional_go','hold')
DOMAINS=('security','recovery','data','operations','business','governance')
def esc(x):return html.escape(str(x),quote=True)
def _text(x,k,c,required=True):
    v=x.get(k)
    if not isinstance(v,str) or (required and not v.strip()):raise ValueError(f'{c} {k}: {"nonempty " if required else ""}text required')
def _iso(v,c,nullable=False):
    if nullable and v=='':return
    try:
        if date.fromisoformat(v).isoformat()!=v:raise ValueError
    except (TypeError,ValueError):raise ValueError(f'{c}: ISO date YYYY-MM-DD required') from None

def validate(data):
    if not isinstance(data,dict):raise ValueError('Expected a release-readiness snapshot object')
    for k in ('title','version','as_of','source','scope','state'):_text(data,k,'snapshot')
    _iso(data['as_of'],'as_of')
    release=data.get('release')
    if not isinstance(release,dict):raise ValueError('release is required')
    for k in ('id','version','environment','population','window','baseline','go_authority','decision_state','decision_source'):_text(release,k,'release',required=k!='decision_source')
    if release['decision_state'] not in DECISIONS:raise ValueError('release decision_state is invalid')
    if release['decision_state']!='pending' and not release['decision_source'].strip():raise ValueError('an actual decision requires a decision source')
    gates=data.get('gates')
    if not isinstance(gates,list) or not gates:raise ValueError('gates must be a nonempty list')
    ids=set()
    for g in gates:
        if not isinstance(g,dict):raise ValueError('Each gate must be an object')
        for k in ('id','label','domain','classification','basis','status','evidence','evidence_ref','observed_on','acceptor','acceptance_state','exception_authority','action','owner','due','source','note'):_text(g,k,'gate',required=k not in ('evidence_ref','observed_on','exception_authority','due','note'))
        if type(g.get('applicable')) is not bool:raise ValueError(f'{g.get("id","gate")}: applicable must be boolean')
        if g['id'] in ids:raise ValueError(f'duplicate gate id: {g["id"]}')
        ids.add(g['id'])
        if g['domain'] not in DOMAINS:raise ValueError(f'{g["id"]}: invalid domain')
        if g['classification'] not in CLASSIFICATIONS:raise ValueError(f'{g["id"]}: invalid classification')
        if g['status'] not in STATUSES:raise ValueError(f'{g["id"]}: invalid status')
        if g['acceptance_state'] not in ACCEPTANCE:raise ValueError(f'{g["id"]}: invalid acceptance state')
        if g['observed_on']:_iso(g['observed_on'],f'{g["id"]} observed_on')
        if g['due']:_iso(g['due'],f'{g["id"]} due')
        if g['status']=='accepted_exception' and g['classification']!='exceptionable':raise ValueError(f'{g["id"]}: accepted exception requires exceptionable classification')
        if g['status'] in ('passed','accepted_exception') and (not g['evidence_ref'] or not g['observed_on']):raise ValueError(f'{g["id"]}: passing evidence needs reference and observation date')
        if g['status']=='accepted_exception' and not g['exception_authority']:raise ValueError(f'{g["id"]}: accepted exception requires exception authority')
    events=data.get('events',[])
    if not isinstance(events,list):raise ValueError('events must be a list')
    event_ids=set()
    for x in events:
        if not isinstance(x,dict):raise ValueError('Each event must be an object')
        for k in ('id','date','label','state','scope','source'):_text(x,k,'event')
        if x['id'] in event_ids:raise ValueError(f'duplicate event id: {x["id"]}')
        event_ids.add(x['id']);_iso(x['date'],f'{x["id"]} date')
    p=data.get('presentation')
    if not isinstance(p,dict):raise ValueError('presentation is required')
    for k in ('eyebrow','headline','lede','default_gate_id','decision'):_text(p,k,'presentation')
    if p['default_gate_id'] not in ids:raise ValueError('default_gate_id must reference gates')
    a=data.get('analysis')
    if not isinstance(a,dict):raise ValueError('analysis is required')
    for k in ('method','applicability_boundary','authorization_boundary','recheck_rule'):_text(a,k,'analysis')
    readiness(data)
    return data

def readiness(data,gates=None):
    rows=data.get('gates',[]) if gates is None else gates;blockers=[];satisfied=[];exceptions=[];unknown=[]
    for g in rows:
        if not g['applicable']:continue
        ok=(g['status']=='passed' and g['acceptance_state'] in ('accepted','not_required')) or (g['classification']=='exceptionable' and g['status']=='accepted_exception' and g['acceptance_state']=='accepted')
        if ok:satisfied.append(g['id'])
        if g['status']=='accepted_exception':exceptions.append(g['id'])
        if g['status'] in ('unknown','not_run'):unknown.append(g['id'])
        if g['classification'] in ('mandatory','exceptionable') and not ok:blockers.append(g['id'])
    recommendation='hold' if blockers else ('conditional_go' if exceptions else 'go_ready')
    return {'recommendation':recommendation,'blockers':blockers,'satisfied':satisfied,'exceptions':exceptions,'unknown':unknown}

def safe(v):
    s='' if v is None else str(v)
    return "'"+s if isinstance(v,str) and s.startswith(('=','+','-','@','\t','\r')) else s
def render_csv(data):
    validate(data);r=data['release'];s=io.StringIO(newline='');w=csv.writer(s,lineterminator='\n')
    w.writerow(['gate_id','gate','domain','classification','basis','applicable','status','evidence','evidence_ref','observed_on','acceptor','acceptance_state','exception_authority','action','owner','due','source','note','release_id','release_version','environment','population','window','baseline','go_authority','actual_decision_state','actual_decision_source','as_of'])
    for g in data['gates']:w.writerow([safe(x) for x in [g['id'],g['label'],g['domain'],g['classification'],g['basis'],g['applicable'],g['status'],g['evidence'],g['evidence_ref'],g['observed_on'],g['acceptor'],g['acceptance_state'],g['exception_authority'],g['action'],g['owner'],g['due'],g['source'],g['note'],r['id'],r['version'],r['environment'],r['population'],r['window'],r['baseline'],r['go_authority'],r['decision_state'],r['decision_source'],data['as_of']]])
    return s.getvalue()
def txt(x,y,v,size=13,fill='#13294b',weight='400',anchor=None):
    a=f' text-anchor="{anchor}"' if anchor else ''
    return f'<text x="{x}" y="{y}" font-family="Arial,sans-serif" font-size="{size}" fill="{fill}" font-weight="{weight}"{a}>{esc(v)}</text>'
def render_svg(data):
    validate(data);summary=readiness(data);width=1440;height=430+len(data['gates'])*66;colors={'passed':'#08766c','failed':'#b42318','not_run':'#a25b00','unknown':'#667085','accepted_exception':'#6f42a6'}
    out=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}" role="img" aria-labelledby="title desc">',f'<title id="title">{esc(data["title"])}</title>',f'<desc id="desc">Independent release gate evidence as of {esc(data["as_of"])}. The recommendation is separate from actual go authority.</desc>','<rect width="100%" height="100%" fill="#f5f7fb"/><rect width="12" height="100%" fill="#173b2d"/>',txt(38,42,data['presentation']['eyebrow'].upper(),12,'#d80b61','800'),txt(38,96,data['presentation']['headline'],40,'#0c234b','800'),txt(38,130,data['presentation']['lede'],15,'#536581')]
    metrics=[('RECOMMENDATION',summary['recommendation'].replace('_',' ').upper()),('BLOCKING GATES',len(summary['blockers'])),('SATISFIED',len(summary['satisfied'])),('ACTUAL DECISION',data['release']['decision_state'].replace('_',' ').upper()),('GO AUTHORITY',data['release']['go_authority'])]
    for i,(k,v) in enumerate(metrics):
        x=38+i*270;out += [f'<rect x="{x}" y="160" width="252" height="86" rx="14" fill="#fff" stroke="#ccd6e5"/>',txt(x+15,184,k,10,'#667085','800'),txt(x+15,219,str(v)[:28],20,'#0c234b','800')]
    y=285
    for g in data['gates']:
        c=colors[g['status']];out += [f'<rect x="38" y="{y}" width="1360" height="52" rx="10" fill="#fff" stroke="#ccd6e5"/>',f'<rect x="38" y="{y}" width="8" height="52" rx="4" fill="{c}"/>',txt(60,y+21,g['id']+' - '+g['label'][:36],13,'#0c234b','800'),txt(530,y+21,g['classification'].replace('_',' ')+' - '+g['domain'],11,'#536581','700'),txt(830,y+21,g['status'].replace('_',' ').upper(),12,c,'800'),txt(1080,y+21,g['acceptance_state'].replace('_',' '),11,'#536581','700'),txt(60,y+41,g['evidence'][:100],10,'#536581')];y+=66
    rec='Blocking conditions: '+(', '.join(summary['blockers']) if summary['blockers'] else 'none in this snapshot')
    out += [txt(38,height-82,rec,12,'#b42318' if summary['blockers'] else '#08766c','800'),txt(38,height-58,'Recommendation is computed from applicable gate evidence; it is not the formal release decision.',11,'#536581'),txt(38,height-36,data['analysis']['authorization_boundary'][:175],10,'#667085'),'</svg>']
    return ''.join(out)
def _json(x):return json.dumps(x,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
def uri(x,m):return 'data:'+m+';base64,'+base64.b64encode(x.encode()).decode()

