def render_html(data,svg=None,csv_text=None):
    validate(data);svg=svg or render_svg(data);csv_text=csv_text or render_csv(data);page=PAGE
    opts=lambda values:''.join(f'<option value="{esc(v)}">{esc(v.replace("_"," "))}</option>' for v in values)
    r=data['release'];rep={'__TITLE__':esc(data['title']),'__EYEBROW__':esc(data['presentation']['eyebrow']),'__HEADLINE__':esc(data['presentation']['headline']),'__LEDE__':esc(data['presentation']['lede']),'__DOMAIN_OPTIONS__':opts(DOMAINS),'__STATUS_OPTIONS__':opts(STATUSES),'__CLASS_OPTIONS__':opts(CLASSIFICATIONS),'__ACCEPT_OPTIONS__':opts(ACCEPTANCE),'__RELEASE__':esc(r['id']+' - '+r['version']),'__ENV__':esc(r['environment']),'__WINDOW__':esc(r['window']),'__POPULATION__':esc(r['population']),'__BASELINE__':esc(r['baseline']),'__APPLICABILITY__':esc(data['analysis']['applicability_boundary']),'__AUTH__':esc(data['analysis']['authorization_boundary']),'__RECHECK__':esc(data['analysis']['recheck_rule']),'__DATA__':_json(data),'__CSV__':_json(csv_text),'__SVG__':_json(uri(svg,'image/svg+xml'))}
    for k,v in rep.items():page=page.replace(k,v)
    return page

