def main(argv=None):
    if hasattr(sys.stdout,'reconfigure'):sys.stdout.reconfigure(encoding='utf-8');sys.stderr.reconfigure(encoding='utf-8')
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('input',nargs='?');p.add_argument('--demo',action='store_true');p.add_argument('--output');a=p.parse_args(argv)
    if a.demo==bool(a.input):p.error('Provide exactly one input JSON or --demo')
    data=demo() if a.demo else validate(json.loads(Path(a.input).read_text(encoding='utf-8')));svg=render_svg(data);csv_text=render_csv(data)
    if not a.output:print(svg);return 0
    stem=Path(a.output);stem.parent.mkdir(parents=True,exist_ok=True);Path(str(stem)+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');Path(str(stem)+'.svg').write_text(svg,encoding='utf-8');Path(str(stem)+'.html').write_text(render_html(data,svg,csv_text),encoding='utf-8');Path(str(stem)+'.csv').write_text(csv_text,encoding='utf-8',newline='');print('Wrote '+', '.join(str(stem)+x for x in ('.html','.svg','.json','.csv')));return 0
if __name__=='__main__':sys.exit(main())
